s='B_DE_GDGBK_IB_DK'
opts={'A':'CBDP','B':'OCBD','C':'CODB','D':'CBDO'}
def ok(f):
    it=iter(f);t=''.join(next(it) if c=='_' else c for c in s)
    bl=[t[i:i+4] for i in range(0,16,4)]
    return all(b[0]=='B' and b[2]=='D' for b in bl) and all(ord(bl[i+1][1])-ord(bl[i][1])==4 for i in range(3)) and all(ord(bl[i+1][3])-ord(bl[i][3])==2 for i in range(3))
fit=[k for k,v in opts.items() if ok(v)]
assert fit==['D']

